{"description":"Sum TOTAL_SNOW for YOW stations over 2025-11-01 to 2026-10-31","command":"python3 - <<'EOF'
import json, glob

files = sorted(glob.glob('/workspace/fetched/yow_p[1-5].json'))
rows = []
for fn in files:
    d = json.load(open(fn))
    rows.extend(d['features'])

# Deduplicate by (station, date)
seen = {}
for f in rows:
    p = f['properties']
    key = (p.get('CLIMATE_IDENTIFIER'), p.get('LOCAL_DATE'))
    if key not in seen:
        seen[key] = p

print(f"Total unique rows: {len(seen)}")

# Filter to our window and YOW stations
window_start = '2025-11-01'
window_end = '2026-10-31'
yow_ids = {'6106000', '6106001'}

total_by_station = {}
missing_by_station = {}
for (cid, date), p in seen.items():
    if cid not in yow_ids:
        continue
    dstr = date[:10]
    if dstr < window_start or dstr > window_end:
        continue
    ts = p.get('TOTAL_SNOW')
    ts_flag = p.get('TOTAL_SNOW_FLAG', '')
    name = p.get('STATION_NAME', '?')
    if ts is not None and str(ts).strip() != '':
        try:
            val = float(ts)
            total_by_station.setdefault(cid, 0.0)
            total_by_station[cid] += val
        except ValueError:
            pass
    else:
        missing_by_station.setdefault(cid, 0)
        missing_by_station[cid] += 1

print("\n=== Totals (mm) ===")
grand = 0
for cid in sorted(total_by_station):
    print(f"  {cid}: {total_by_station[cid]:.1f} mm")
    grand += total_by_station[cid]
print(f"  GRAND TOTAL: {grand:.1f} mm")

print("\n=== Missing/None days ===")
for cid in sorted(missing_by_station):
    print(f"  {cid}: {missing_by_station[cid]} days with no TOTAL_SNOW value")

# Also show per-month breakdown for the main station
print("\n=== Monthly breakdown (6106001 OTTAWA INTL A) ===")
monthly = {}
for (cid, date), p in seen.items():
    if cid != '6106001': continue
    dstr = date[:10]
    if dstr < window_start or dstr > window_end: continue
    ts = p.get('TOTAL_SNOW')
    if ts is not None and str(ts).strip():
        try:
            m = dstr[:7]
            monthly.setdefault(m, 0.0)
            monthly[m] += float(ts)
        except ValueError: pass
for m in sorted(monthly):
    print(f"  {m}: {monthly[m]:.1f} mm")

# Same for 6106000
print("\n=== Monthly breakdown (6106000 OTTAWA MACDONALD-CARTIER INT'L A) ===")
monthly2 = {}
for (cid, date), p in seen.items():
    if cid != '6106000': continue
    dstr = date[:10]
    if dstr < window_start or dstr > window_end: continue
    ts = p.get('TOTAL_SNOW')
    if ts is not None and str(ts).strip():
        try:
            m = dstr[:7]
            monthly2.setdefault(m, 0.0)
            monthly2[m] += float(ts)
        except ValueError: pass
for m in sorted(monthly2):
    print(f"  {m}: {monthly2[m]:.1f} mm")
EOF"}

